from mocaxpy.MocaxException import *
from mocaxpy.MocaxDomain import *
from mocaxpy.MocaxNs import *
from mocaxpy.MocaxSpecialPoints import *

if sys.version_info.major >= 3:
    xrange = range


def mocax_validate_domain_special_points(domain, special_points, num_dimensions=0):
    """
    Validates a set of special points against a Mocax function domain.

    @param[in] domain The function domain. Allowed types: mocaxpy.MocaxDomain.MocaxDomain
    @param[in] special_points The set of special points. Allowed types: mocaxpy.MocaxSpecialPoints.MocaxSpecialPoints
    @param[in] num_dimensions An optionally required dimensionality.
                              If a value of zero or less is passed, the dimensionality will be taken from the domain.
                              Allowed types: @c int, @c long, @c None
    """

    if not isinstance(domain, MocaxDomain):
        raise TypeError("domain is expected to be of type MocaxDomain. " + type(domain).__name__ + " received instead")
    if not isinstance(special_points, MocaxSpecialPoints):
        raise TypeError("special_points is expected to be of type MocaxSpecialPoints. " +
                        type(special_points).__name__ + " received instead")
    if not isinstance(num_dimensions, (int, long, str, type(None))):
        raise TypeError("num_dimensions is expected to be an integer, a string parsable to an integer, or None. " +
                        type(num_dimensions).__name__ + " received instead")

    if num_dimensions is None:
        num_dimensions = int(0)
    else:
        num_dimensions = int(num_dimensions)

    if domain.get_num_dimensions() != special_points.get_num_dimensions():
        raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The special points dimensionality is different than the domain's."
                                    " domain.get_num_dimensions() != special_points.get_num_dimensions(); " +
                             str(domain.get_num_dimensions()) + " != " + str(special_points.get_num_dimensions()))
    if isinstance(num_dimensions, int) and num_dimensions > 0:
        if domain.get_num_dimensions() != num_dimensions:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The domain dimensionality doesn't match the expected."
                                        " domain.get_num_dimensions() != num_dimensions; " +
                                 str(domain.get_num_dimensions()) + " != " + str(num_dimensions))
        if (special_points.get_num_dimensions() != num_dimensions):
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The special points dimensionality doesn't match the expected."
                                        " special_points.get_num_dimensions() != num_dimensions; " +
                                 str(special_points.get_num_dimensions()) + " != " + str(num_dimensions))
    p = 0.0
    for i in xrange(special_points.get_num_dimensions()):
        for j in xrange(special_points.get_num_special_points_for_dimension(i)):
            p = special_points.get_point(i, j)
            if p <= domain.get_x_min( i ) or p >= domain.get_x_max( i ):
                raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_SPECIAL_POINTS_OUTSIDE_DOMAIN)


def mocax_validate_ns_special_points(n, special_points, ignore_first_dimension=False, num_dimensions=0):
    """
    Validates a set of accuracy parameters against a set of special points.

    @param[in] n The set of accuracy parameter. Allowed types: mocaxpy.MocaxNs.MocaxNs
    @param[in] special_points The set of special points. Allowed types: mocaxpy.MocaxSpecialPoints.MocaxSpecialPoints
    @param[in] ignore_first_dimension: Whether to ignore the first dimension
               (i.e., that dimension will use an error threshold) or not.
               Allowed types: @c bool
    @param[in] num_dimensions An optionally required dimensionality. If a value of zero or less is passed,
                              the dimensionality will be taken from the set of special points.
                              Allowed types: @c int, @c long, @c None
    """

    if not isinstance(n, MocaxNs):
        raise TypeError("n is expected to be of type MocaxNs. " + type(n).__name__ + " received instead")
    if not isinstance(special_points, MocaxSpecialPoints):
        raise TypeError("special_points is expected to be of type MocaxSpecialPoints. " +
                        type(special_points).__name__ + " received instead")
    if not isinstance(ignore_first_dimension, bool):
        raise TypeError("ignore_first_dimension is expected to be of type bool. " +
                        type(ignore_first_dimension).__name__ + " received instead")
    if not isinstance(num_dimensions, (int, long, str, type(None))):
        raise TypeError("num_dimensions is expected to be an integer, a string parsable to an integer, or None. " +
                        type(num_dimensions).__name__ + " received instead")

    if ignore_first_dimension:
        offset = 1
    else:
        offset = 0

    if isinstance(num_dimensions, int) and num_dimensions > 0:
        if n.get_num_dimensions() + offset != num_dimensions:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The accuracy parameters dimensionality doesn't match the expected."
                                        " n.get_num_dimensions()" + (" + 1" if ignore_first_dimension else "") +
                                 " != num_dimensions; " + str(n.get_num_dimensions()) + " != " + str(num_dimensions))
    if special_points is not None:
        if n.get_num_dimensions() + offset != special_points.get_num_dimensions():
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The special points dimensionality is different than the accuracy parameters'."
                                        " n.get_num_dimensions() != special_points.get_num_dimensions(); " +
                                 str(n.get_num_dimensions()) + " != " + str(special_points.get_num_dimensions()))
        if isinstance(num_dimensions, int) and num_dimensions > 0:
            if special_points.get_num_dimensions() != num_dimensions:
                raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The special points dimensionality doesn't match the expected."
                                            " specia_points.get_num_dimensions() != num_dimensions; " +
                                     str(special_points.get_num_dimensions()) + " != " + str(num_dimensions))
        for i in xrange(n.get_num_dimensions()):
            if n.get_num_ns_for_dimension(i) != 1 and n.get_num_ns_for_dimension(i) != \
                            special_points.get_num_special_points_for_dimension(i + offset) + 1:
                raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_INVALID_NUMBER_OF_N_VALUES, "The number of Ns for a given dimension has to be either 1 or the number of"
                                            " special points + 1 for that dimension. n.get_num_ns_for_dimension(" +
                                     str(i) + ") = " + str(special_points.get_num_dimensions()) +
                                     "; special_points.get_num_special_points_for_dimension(" + str(i + offset) +
                                     ") = " + str(special_points.get_num_special_points_for_dimension(i + offset)))
    else:
        if n.has_multiple_sizes_per_dimension():
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_INVALID_NUMBER_OF_N_VALUES, "When no special points are provided, only one N per dimension is expected"
                                        " (argument n has several accuracy parameters in at least one dimension). ")


def mocax_validate_domain_ns(domain, n, ignore_first_dimension=False, num_dimensions=0):
    """
    Validates a set of accuracy parameters against a Mocax function domain.

    @param[in] domain The function domain. Allowed types: mocaxpy.MocaxDomain.MocaxDomain
    @param[in] n The set of accuracy parameters. Allowed types: mocaxpy.MocaxNs.MocaxNs.
    @param[in] ignore_first_dimension Whether to ignore the first dimension
                                      (i.e., that dimension will use an error threshold) or not.
                                      Allowed types: @c bool
    @param[in] num_dimensions An optionally required dimensionality.
                              If a value of zero or less is passed, the dimensionality will be taken from the domain.
                              Allowed types: @c int, @c long, @c None
    """

    if not isinstance(domain, MocaxDomain):
        raise TypeError("domain is expected to be of type MocaxDomain. " + type(domain).__name__ + " received instead")
    if not isinstance(n, MocaxNs):
        raise TypeError("n is expected to be of type MocaxNs. " + type(n).__name__ + " received instead")
    if not isinstance(ignore_first_dimension, bool):
        raise TypeError("ignore_first_dimension is expected to be of type bool. " +
                        type(ignore_first_dimension).__name__ + " received instead")
    if not isinstance(num_dimensions, (int, long, str, type(None))):
        raise TypeError("num_dimensions is expected to be an integer, a string parsable to an integer, or None. " +
                        type(num_dimensions).__name__ + " received instead")

    if ignore_first_dimension:
        offset = 1
    else:
        offset = 0

    if n.get_num_dimensions() + offset != domain.get_num_dimensions():
        raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The domain dimensionality is different than the accuracy parameters'" +
                             (" (ignoring the first dimension)" if ignore_first_dimension else "") +
                             ". n.get_num_dimensions()" + (" + 1" if ignore_first_dimension else "") +
                             " != domain.get_num_dimensions(); " + str(n.get_num_dimensions() + offset) +
                             " != " + str(domain.get_num_dimensions()))

    if isinstance(num_dimensions, int) and num_dimensions > 0:
        if n.get_num_dimensions() + offset != num_dimensions:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The accuracy parameters dimensionality doesn't match the expected."
                                        " n.get_num_dimensions()" + (" + 1" if ignore_first_dimension else "") +
                                 " != num_dimensions; " + str(n.get_num_dimensions()) + " != " + str(num_dimensions))
        if domain.get_num_dimensions() != num_dimensions:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The domain dimensionality doesn't match the expected. "
                                        "domain.get_num_dimensions() != num_dimensions; " +
                                 str(domain.get_num_dimensions()) + " != " + str(num_dimensions))

    if n.get_num_dimensions() + offset != domain.get_num_dimensions():
        raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The domain dimensionality is different than the accuracy parameters'" +
                             (" (ignoring the first dimension)" if ignore_first_dimension else "") +
                             ". n.get_num_dimensions()" + (" + 1" if ignore_first_dimension else "") +
                             " != domain.get_num_dimensions(); " + str(n.get_num_dimensions() + offset) +
                             " != " + str(domain.get_num_dimensions()))
    if isinstance(num_dimensions, int) and num_dimensions > 0:
        if n.get_num_dimensions() + offset != num_dimensions:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The accuracy parameters dimensionality doesn't match the expected."
                                        " n.get_num_dimensions()" + (" + 1" if ignore_first_dimension else "") +
                                 " != num_dimensions; " + str(n.get_num_dimensions()) + " != " + str(num_dimensions))
        if domain.get_num_dimensions() != num_dimensions:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The domain dimensionality doesn't match the expected."
                                        " domain.get_num_dimensions() != num_dimensions; " +
                                 str(domain.get_num_dimensions()) + " != " + str(num_dimensions))


def mocax_validate_domain_ns_special_points(domain, n, special_points, ignore_first_dimension=False, num_dimensions=0):
    """
    Performs all the validations, depending on the received parameters (use None to not validate one in particular).

    @param[in] domain The function domain. Allowed types: mocaxpy.MocaxDomain.MocaxDomain
    @param[in] n The set of accuracy parameters. Allowed types: mocaxpy.MocaxNs.MocaxNs
    @param[in] special_points The set of special points. Allowed types: mocaxpy.MocaxSpecialPoints.MocaxSpecialPoints
    @param[in] ignore_first_dimension Whether to ignore the first dimension
                                      (i.e., that dimension will use an error threshold) or not.
                                      Allowed types: @c bool
    @param[in] num_dimensions An optionally required dimensionality. Allowed types: @c int, @c long, @c None
    """

    if domain is not None and n is not None:
        mocax_validate_domain_ns(domain, n, ignore_first_dimension, num_dimensions)
    if domain is not None and special_points is not None:
        mocax_validate_domain_special_points(domain, special_points, num_dimensions)
    if n is not None and special_points is not None:
        mocax_validate_ns_special_points(n, special_points, ignore_first_dimension, num_dimensions)
